import java.util.*;

class Solution {
  public int maximumLength(int[] nums, int k) {
    int maxValue = 100001;
    int[][] ending = new int[k + 1][maxValue];
    int[] best = new int[k + 1];
    int answer = 0;
    for (int value : nums) {
      int[] current = new int[k + 1];
      for (int changes = 0; changes <= k; changes++) {
        current[changes] = ending[changes][value] + 1;
        if (changes > 0) current[changes] = Math.max(current[changes], best[changes - 1] + 1);
        current[changes] = Math.max(current[changes], 1);
      }
      for (int changes = 0; changes <= k; changes++) {
        ending[changes][value] = Math.max(ending[changes][value], current[changes]);
        best[changes] = Math.max(best[changes], current[changes]);
        answer = Math.max(answer, current[changes]);
      }
    }
    return answer;
  }
}
